CREATE DATABASE IF NOT EXISTS kelompok6 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kelompok6;
CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(150) NOT NULL UNIQUE, description TEXT NULL, image VARCHAR(255) NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190) NOT NULL, sku VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(220) NOT NULL UNIQUE, category_id INT UNSIGNED NULL, description TEXT NULL, long_description MEDIUMTEXT NULL, price DECIMAL(12,2) NOT NULL DEFAULT 0, sale_price DECIMAL(12,2) NULL, stock INT UNSIGNED NOT NULL DEFAULT 0, image VARCHAR(255) NULL, active TINYINT(1) NOT NULL DEFAULT 1, featured TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_products_active(active), INDEX idx_products_category(category_id), INDEX idx_products_created(created_at), CONSTRAINT fk_products_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(40) NOT NULL UNIQUE, customer_name VARCHAR(190) NOT NULL, whatsapp VARCHAR(60) NOT NULL, email VARCHAR(190) NOT NULL, province VARCHAR(120) NOT NULL, city VARCHAR(120) NOT NULL, district VARCHAR(120) NULL, address TEXT NOT NULL, postal_code VARCHAR(20) NULL, notes TEXT NULL, subtotal DECIMAL(12,2) NOT NULL, shipping_fee DECIMAL(12,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL, status ENUM('Pending','Awaiting Payment','Paid','Processing','Shipped','Completed','Cancelled') NOT NULL DEFAULT 'Pending', payment_status VARCHAR(40) NOT NULL DEFAULT 'Awaiting Payment', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_orders_status(status), INDEX idx_orders_created(created_at)) ENGINE=InnoDB;
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id INT UNSIGNED NULL, product_name VARCHAR(190) NOT NULL, sku VARCHAR(100) NOT NULL, unit_price DECIMAL(12,2) NOT NULL, quantity INT UNSIGNED NOT NULL, line_total DECIMAL(12,2) NOT NULL, CONSTRAINT fk_orderitems_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_orderitems_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE newsletter_subscribers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT INTO settings(setting_key,setting_value) VALUES ('store_name','KELOMPOK 6'),('announcement','CURATED FOR YOUR LIFESTYLE.'),('hero_heading','THE ART OF EVERYDAY LIVING'),('hero_description','Discover a carefully curated collection designed for modern lifestyles.'),('hero_cta','EXPLORE COLLECTION'),('hero_link','shop.php'),('store_description','Curated for your lifestyle.'),('footer_text','Thoughtfully selected pieces for everyday living.'),('shipping_fee','0'),('about_text','A thoughtful edit of enduring essentials, selected with care for the way you live.') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
